import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百八十二章 水稻被割断","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/182第一百八十二章 水稻被割断.md","filePath":"meditation/巴利文大藏经/182第一百八十二章 水稻被割断.md"}'),r={name:"meditation/巴利文大藏经/182第一百八十二章 水稻被割断.md"};function _(n,p,i,s,d,c){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="第一百八十二章-水稻被割断" tabindex="-1">第一百八十二章 水稻被割断 <a class="header-anchor" href="#第一百八十二章-水稻被割断" aria-label="Permalink to &quot;第一百八十二章 水稻被割断&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部17相应35经/离去不久经(利得恭敬相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在王舍城的耆闍崛山，有一天，提婆达多分裂僧团、破坏僧团的和睦后，就带着一些被他迷惑的出家人离开了佛陀。众多的出家人聚集在佛陀的身边，他们对提婆达多分裂僧团、破坏僧团和睦的事情很气愤。佛陀对他们说：“弟子们，你们不要情绪激愤，你们不要生气愤怒，这样会障碍你们的修行。你们应该熄灭内心中的怒火，你们应该除灭内心中愤怒的烦恼。提婆达多贪求世间人丰厚的供养，贪求富贵舒适的生活，贪求世间人虔诚的尊敬、恭敬，贪求家喻户晓的名誉声望，他清净的修行将会因为贪欲而凋谢，他将会被这些贪欲谋害，他将会因为贪欲而败亡。</p><p>弟子们，就如同结出果实的芭蕉树，将会被世间的人争抢、采摘芭蕉果实一样，这些想吃芭蕉果实或者想将芭蕉果实拿去卖的人，他们为了获得芭蕉果实将会割断芭蕉树的叶子，砍断芭蕉树的茎干，甚至于挖断芭蕉根。芭蕉树因为结出果实而被世间的人摧残、伤害，最后导致芭蕉树凋落、灭亡。同样的道理，提婆达多贪求世间人丰厚的供养，贪求富贵舒适的生活，贪求世间人虔诚的尊敬、恭敬，贪求家喻户晓的名誉声望，他清净的修行将会因为贪欲而凋谢，他将会被这些贪欲谋害，他将会因为贪欲而败亡。</p><p>弟子们，就如同一些竹子一旦开花结果就会枯萎死亡。同样的道理，提婆达多贪求世间人丰厚的供养，贪求富贵舒适的生活，贪求世间人虔诚的尊敬、恭敬，贪求家喻户晓的名誉声望，他清净的修行将会因为贪欲而凋谢，他将会被这些贪欲谋害，他将会因为贪欲而败亡。</p><p>弟子们，就如同结出成熟果实的水稻，世间的人会为了获得稻谷而割断水稻的茎杆，水稻将会由此被割断死亡。同样的道理，提婆达多贪求世间人丰厚的供养，贪求富贵舒适的生活，贪求世间人虔诚的尊敬、恭敬，贪求家喻户晓的名誉声望，他清净的修行将会因为贪欲而凋谢，他将会被这些贪欲谋害，他将会因为贪欲而败亡。</p><p>弟子们，就如同马与驴子生出来的骡子无法繁衍后代一样，骡子无法生育下一代，它的后代将会灭亡、灭尽。同样的道理，提婆达多贪求世间人丰厚的供养，贪求富贵舒适的生活，贪求世间人虔诚的尊敬、恭敬，贪求家喻户晓的名誉声望，他清净的修行将会因为贪欲而凋谢，他将会被这些贪欲谋害，他将会因为贪欲而败亡。</p><p>芭蕉树因为果实而被世间的人摧残、伤害走向灭亡，竹子因为开花结果而枯萎死亡，水稻因为稻谷而被世间的人割断死亡，骡子因为无法繁育后代而断子绝孙。贪婪的人、恶人因为利益而败亡。”</p><p>这时，佛陀说偈言：</p><p>「芭蕉为果灭，</p><p>水稻为果亡，</p><p>竹子开花死，</p><p>骡子无子孙，</p><p>恶人为利殁。」</p><p>佛陀继续对出家弟子们说：“弟子们，世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望就是这样的让人内心颤抖恐怖，就是这样的让人内心激烈搅动，就是这样的让人内心暴躁不安。</p><p>世间人丰厚的供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望是修行人内心达到清净安稳的障碍，是修行人内心挣脱束缚捆绑的阻碍。弟子们，因此，你们应该这样去修行：「我们要舍离、放弃已经获得的丰厚供养，我们要舍离、放弃已经获得的富贵舒适的生活，我们要舍离、放弃已经获得的世间人虔诚的尊敬、恭敬，我们要舍离、放弃已经获得的家喻户晓的名誉声望。而且我们不要执着和挂念这些已经获得的丰厚供养，不要执着和挂念这些已经获得的富贵舒适的生活，不要执着和挂念这些已经获得的世间人虔诚的尊敬、恭敬，不要执着和挂念这些已经获得的家喻户晓的名誉声望。我们不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望扰乱我们的内心；不要让丰厚供养，富贵舒适的生活，世间人虔诚的尊敬、恭敬，家喻户晓的名誉声望让我们胡思乱想、内心散乱。」弟子们，你们就应该这样的去修行。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',18)]))}const f=t(r,[["render",_]]);export{m as __pageData,f as default};
